var n=`0743-genfo`;var t=`world-0743`;var s=`ET`;var o=`eastern-africa`;var r=8;var a=46;var g={en:`Genfo`,ua:`Генфо`};var h={en:`Genfo is a Ethiopia classic prepared with barley flour, niter kibbeh. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Генфо, страва кухні країни Ефіопія зі складниками: ячмінне борошно, пряне масло нітер кіббе. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`water`,800,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 22 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 22 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:22,i:[[`barley-flour`,340,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 9 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 9 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:9,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`niter-kibbeh`,50,`g`],[`berbere`,6,`g`]]}];var u={slug:n,id:t,country:`ET`,region:o,servings:8,minutes:46,title:g,text:h,steps:l};export{s as country,u as default,t as id,a as minutes,o as region,r as servings,n as slug,l as steps,h as text,g as title};